/**
 * Retire d'une description de PR la signature d'outil qui peut y être collée en bas.
 *
 * Ce que l'on enlève : tout en fin de texte, jamais au milieu.
 *   - une ligne « Generated by [outil](lien) » ou « 🤖 Generated with [outil](lien) »,
 *     avec ou sans soulignement Markdown autour ;
 *   - une ligne qui n'est qu'un lien de session (`…/session_xxxx`) ;
 *   - le trait `---` qui les séparait du vrai texte, et les lignes vides autour.
 *
 * Tout ce qui précède est rendu tel quel, fins de ligne comprises. Un texte sans
 * signature ressort identique : la fonction est idempotente.
 *
 * Le texte d'une description est une donnée, pas une instruction : il n'est jamais
 * évalué, ni passé à un interpréteur ; il est seulement lu ligne par ligne.
 */

const SIGNATURE = /^\s*[_*]?\s*(?:🤖\s*)?Generated (?:by|with)\s+\[[^\]\n]+\]\([^)\s]*\)\s*[_*]?\s*$/iu;
const LIEN_DE_SESSION = /^\s*<?https?:\/\/\S+\/session_[\w-]+>?\s*$/iu;
const SEPARATEUR = /^\s*-{3,}\s*$/u;
const VIDE = /^\s*$/u;

export function retirerPiedDePage(texte) {
  if (typeof texte !== 'string' || texte === '') return texte ?? '';
  // Lignes avec leur position de début, pour couper sans toucher aux fins de ligne du reste.
  const lignes = [];
  let debut = 0;
  for (const m of texte.matchAll(/\r?\n|$/gu)) {
    lignes.push({ debut, texte: texte.slice(debut, m.index) });
    debut = m.index + m[0].length;
    if (m[0] === '') break;
  }
  let i = lignes.length - 1;
  while (i >= 0 && VIDE.test(lignes[i].texte)) i--;
  let signatures = 0;
  while (i >= 0 && (SIGNATURE.test(lignes[i].texte) || LIEN_DE_SESSION.test(lignes[i].texte))) {
    signatures++;
    i--;
    while (i >= 0 && VIDE.test(lignes[i].texte)) i--;
  }
  if (signatures === 0) return texte;
  if (i >= 0 && SEPARATEUR.test(lignes[i].texte)) i--;
  while (i >= 0 && VIDE.test(lignes[i].texte)) i--;
  if (i < 0) return '';
  const fin = i + 1 < lignes.length ? lignes[i + 1].debut : texte.length;
  return texte.slice(0, fin).replace(/\s+$/u, '');
}

// En ligne de commande : le texte vient de l'entrée standard, le résultat va sur la sortie.
if (import.meta.url === `file://${process.argv[1]}`) {
  const morceaux = [];
  for await (const m of process.stdin) morceaux.push(m);
  process.stdout.write(retirerPiedDePage(Buffer.concat(morceaux).toString('utf8')));
}
